function QRUser(a){new QRCode("qrcodeUser",{text:a,width:90,height:90,colorDark:"#000000",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.H})}function QRAtasan(a){new QRCodeStyling({width:120,height:120,type:"svg",data:a,image:"/asset/img/Lambang_KotaSingkawang.webp",dotsOptions:{color:"#000000",type:"rounded"}}).append(document.getElementById("qrcodeAtasan"))}let params=new URL(document.location).searchParams,date=params.get("date");console.log(periode);async function getQR(){await $.ajax({url:"/api/monthly/signaute?periode="+date+"&nik="+nik,method:"GET",success:function(a){if(console.log(a),a.data.stausUser){let t=a.data.aprovUser.user.nama+" telah membuat laporan periode "+periode+" Pada tanggal "+a.data.aprovUser.date;QRUser(t)}if(a.data.stausAtasan){let t=a.data.aprovAtasan.atasan.nama+" telah menyetujui laporan periode "+periode+" Pada tanggal "+a.data.aprovAtasan.date;$("#nameAtasan").text(a.data.aprovAtasan.atasan.nama),$("#nipAtasan").text("NIP. "+a.data.aprovAtasan.atasan.nip),QRAtasan(t)}}})}$(document).ready(async function(){getQR(),setTimeout(function(){window.print()},3e3),console.log("ready!")});
